// Generated by scripts/sync-help.mjs from pzza-code-web/components/home/ansi.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Renders a real terminal capture (`tmux capture-pane -e`) cell for cell: the
 * text and SGR styling exactly as the program wrote them, in the app's dark
 * terminal theme. Lines are not rewrapped; the capture was taken at the tile's
 * own width.
 *
 * The screens are drawn in the browser only. They are sample output, a few
 * thousand styled spans across the page, and the scenes stay hidden until
 * their Stage has measured anyway; leaving them out of the server HTML keeps
 * the page small and its text about the product.
 */
import { useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore, type CSSProperties, type RefObject } from "react";
import { CAPTURES, type CaptureId } from "./captures";

// The app's dark terminal theme (src/theme/themes.ts): ANSI 0-15 and the default foreground.
const ANSI16 = ["#11151c", "#ea6c73", "#91b362", "#f9af4f", "#53bdfa", "#fae994", "#90e1c6", "#c7c7c7", "#686868", "#f07178", "#c2d94c", "#ffb454", "#59c2ff", "#ffee99", "#95e6cb", "#ffffff"];
const FG = "#bfbdb6";

/** An xterm 256-colour index as CSS: 0-15 from the theme, then the 6x6x6 cube and the grey ramp. */
function x256(n: number): string {
  if (n < 16) return ANSI16[n];
  if (n < 232) {
    const i = n - 16;
    const level = (v: number) => (v === 0 ? 0 : 55 + v * 40);
    return `rgb(${level(Math.floor(i / 36))} ${level(Math.floor(i / 6) % 6)} ${level(i % 6)})`;
  }
  const g = 8 + (n - 232) * 10;
  return `rgb(${g} ${g} ${g})`;
}

interface Style {
  fg?: string;
  bg?: string;
  bold?: boolean;
  dim?: boolean;
  italic?: boolean;
  underline?: boolean;
  strike?: boolean;
  inverse?: boolean;
}
export interface Run {
  text: string;
  style: Style;
}

// The tile's own background, for inverse video on default colours.
const BG = "#0b0e14";

/** Applies one SGR sequence's parameters to a style. */
function applySgr(style: Style, params: number[]): Style {
  const next = { ...style };
  for (let i = 0; i < params.length; i += 1) {
    const p = params[i];
    if (p === 0) {
      for (const key of Object.keys(next) as (keyof Style)[]) delete next[key];
    } else if (p === 1) next.bold = true;
    else if (p === 2) next.dim = true;
    else if (p === 3) next.italic = true;
    else if (p === 4) next.underline = true;
    else if (p === 7) next.inverse = true;
    else if (p === 9) next.strike = true;
    else if (p === 22) {
      next.bold = false;
      next.dim = false;
    } else if (p === 23) next.italic = false;
    else if (p === 24) next.underline = false;
    else if (p === 27) next.inverse = false;
    else if (p === 29) next.strike = false;
    else if (p >= 30 && p <= 37) next.fg = x256(p - 30);
    else if (p >= 90 && p <= 97) next.fg = x256(p - 90 + 8);
    else if (p >= 40 && p <= 47) next.bg = x256(p - 40);
    else if (p >= 100 && p <= 107) next.bg = x256(p - 100 + 8);
    else if (p === 39) delete next.fg;
    else if (p === 49) delete next.bg;
    else if (p === 38 || p === 48) {
      const key = p === 38 ? "fg" : "bg";
      if (params[i + 1] === 5) {
        next[key] = x256(params[i + 2] ?? 0);
        i += 2;
      } else if (params[i + 1] === 2) {
        next[key] = `rgb(${params[i + 2] ?? 0} ${params[i + 3] ?? 0} ${params[i + 4] ?? 0})`;
        i += 4;
      }
    }
  }
  return next;
}

/** One capture as lines of styled runs; OSC sequences (hyperlinks) are dropped, their text kept. */
export function parseAnsi(text: string): Run[][] {
  const clean = text.replace(/\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)/g, "");
  return clean.split("\n").map((line) => {
    const runs: Run[] = [];
    let style: Style = {};
    let buffer = "";
    const flush = () => {
      if (buffer) runs.push({ text: buffer, style });
      buffer = "";
    };
    for (let i = 0; i < line.length; i += 1) {
      if (line[i] === "\x1b" && line[i + 1] === "[") {
        const end = line.slice(i + 2).search(/[A-Za-z]/);
        if (end < 0) break;
        const command = line[i + 2 + end];
        if (command === "m") {
          flush();
          const body = line.slice(i + 2, i + 2 + end);
          style = applySgr(style, body === "" ? [0] : body.split(";").map((n) => Number(n) || 0));
        }
        i += 2 + end;
      } else {
        buffer += line[i];
      }
    }
    flush();
    return runs;
  });
}

function css(style: Style): CSSProperties | undefined {
  let { fg, bg } = style;
  if (style.inverse) [fg, bg] = [bg ?? BG, fg ?? FG];
  const out: CSSProperties = {};
  if (fg) out.color = fg;
  if (bg) out.background = bg;
  if (style.bold) out.fontWeight = 700;
  if (style.dim) out.opacity = 0.6;
  if (style.italic) out.fontStyle = "italic";
  const lines = [style.underline ? "underline" : "", style.strike ? "line-through" : ""].filter(Boolean).join(" ");
  if (lines) out.textDecoration = lines;
  return Object.keys(out).length ? out : undefined;
}

/** Claude Code's spinner, which runs out through its glyphs and back, one per SPINNER_MS. */
export const SPINNER = ["·", "✢", "✳", "✶", "✻", "✽", "✻", "✶", "✳", "✢"];
export const SPINNER_MS = 120;

// Block glyphs are drawn to fill their cell, as a terminal does.
const BLOCKS = /[▀-▟]/;

// False while rendering on the server and hydrating, true once in the browser.
const noSubscription = () => () => {};
const useInBrowser = () => useSyncExternalStore(noSubscription, () => true, () => false);

/**
 * Replaying a captured Claude Code exchange: how many lines of the answer are
 * out so far, and while the agent is still at it, its working line (the
 * spinner glyph and the verb with elapsed time) in place of the "done" line.
 */
export interface Replay {
  shown: number;
  working: { glyph: string; text: string } | null;
}

/** Where the last exchange sits in a capture: the question asked and its closing status line. */
interface Exchange {
  question: number;
  status: number;
}

function findExchange(lines: Run[][]): Exchange | null {
  const plain = lines.map((runs) => runs.map((run) => run.text).join(""));
  let question = -1;
  plain.forEach((line, i) => {
    if (/^❯ \S/.test(line)) question = i;
  });
  const status = plain.findIndex((line, i) => i > question && /^[✻✶✳✢·✽] /.test(line));
  return question >= 0 && status > question ? { question, status } : null;
}

/** The number of answer lines a capture has to replay, for pacing a scene's loop. */
export function answerLength(id: CaptureId): number {
  const exchange = findExchange(parseAnsi(CAPTURES[id]));
  // The answer runs from after the question to the blank line above the status.
  return exchange ? exchange.status - exchange.question - 2 : 0;
}

/**
 * A captured screen; the newest lines stay in view when it is taller than its
 * tile (see TerminalLines). With `replay` the last answer is rebuilt as the
 * agent writes it: the lines so far, then the working line, with the prompt
 * and footer below kept where they are.
 */
export function AnsiScreen({ id, replay }: { id: CaptureId; replay?: Replay }) {
  const inBrowser = useInBrowser();
  const lines = useMemo(() => (inBrowser ? parseAnsi(CAPTURES[id]) : []), [inBrowser, id]);
  const exchange = useMemo(() => findExchange(lines), [lines]);

  let shown: TerminalRow[] = lines.map((runs) => ({ runs }));
  if (replay && exchange) {
    const { question, status } = exchange;
    const statusRuns = lines[status];
    // The glyph keeps the capture's own colour; the verb reads like the status text.
    const working: Run[] | null = replay.working
      ? [
          { text: replay.working.glyph, style: statusRuns[0]?.style ?? {} },
          { text: ` ${replay.working.text}`, style: statusRuns[1]?.style ?? statusRuns[0]?.style ?? {} },
        ]
      : null;
    // As in the terminal, the working line sits right under the latest output
    // and the prompt below moves down as the answer grows.
    const answer = lines.slice(question + 1, status - 1);
    shown = [
      ...lines.slice(0, question + 1).map((runs) => ({ runs })),
      ...answer.slice(0, replay.shown).map((runs) => ({ runs, fresh: true })),
      ...(working ? [{ runs: [] }, { runs: working }] : lines.slice(status - 1, status + 1).map((runs) => ({ runs }))),
      ...lines.slice(status + 1).map((runs) => ({ runs })),
    ];
  }

  return <TerminalLines rows={shown} />;
}

/** How many whole rows the terminal under `screen` has room for, once measured. */
function useFittingRows(screen: RefObject<HTMLDivElement>): number | null {
  const [rows, setRows] = useState<number | null>(null);
  useLayoutEffect(() => {
    const el = screen.current;
    const box = el?.parentElement;
    if (!el || !box) return;
    const update = () => {
      const line = parseFloat(getComputedStyle(el).lineHeight);
      if (line > 0) setRows(Math.floor(box.clientHeight / line));
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(box);
    return () => observer.disconnect();
  }, [screen]);
  return rows;
}

/** The rows a terminal of `fit` rows shows: the newest, scrolled by whole rows, never through the banner. */
function scrolledToFit(rows: TerminalRow[], fit: number): TerminalRow[] {
  const over = rows.length - fit;
  if (over <= 0 || fit <= 0) return rows;
  const blank = rows.findIndex(({ runs }) => runs.every((run) => !run.text.trim()));
  // An agent's banner is a few rows (Claude Code's logo is three) and a blank one.
  const banner = blank > 0 && blank <= 4 ? blank + 1 : 0;
  return rows.slice(over <= banner ? banner : over);
}

/** One line as drawn; `fresh` plays the line's entrance as it is written out. */
export interface TerminalRow {
  runs: Run[];
  fresh?: boolean;
}

/**
 * Terminal lines drawn cell for cell, as a captured screen is. Like a terminal
 * it keeps the newest rows in view and scrolls by whole rows; when only part of
 * the agent's banner (its logo and version, up to the first blank row) would
 * show, the whole banner goes, so no logo is ever drawn half cut.
 */
export function TerminalLines({ rows }: { rows: TerminalRow[] }) {
  const screen = useRef<HTMLDivElement>(null);
  const fit = useFittingRows(screen);
  const visible = fit === null ? rows : scrolledToFit(rows, fit);
  return (
    <div className="tm" ref={screen}>
      {visible.map(({ runs, fresh }, i) => (
        <div key={i} className={fresh ? "tm-pre tm-fresh" : "tm-pre"}>
          {runs.length
            ? runs.map((run, j) => (
                <span key={j} className={BLOCKS.test(run.text) ? "tm-block" : undefined} style={css(run.style)}>
                  {run.text}
                </span>
              ))
            : " "}
        </div>
      ))}
    </div>
  );
}
